    blit_screen(m_frame->GetScreenRect(), "printer-menu-other-printers");
    // TEMPORARY (token-sync comparison, not for commit): draw the chip
    // and the open menu offscreen, light then dark.
    menu->close();
    wxYield();
    for (const bool dark : {false, true}) {
        header->apply_appearance(dark);
        header->open_printer_menu();
        for (int i = 0; i < 5; ++i) { wxYield(); wxMilliSleep(30); }
        HeaderMenu* shown = visible_header_menu();
        auto* chip = dynamic_cast<PrinterFilamentChip*>(wxWindow::FindWindowByName("Printer and filament", header));
        if (shown == nullptr || chip == nullptr) { check(false, "temp_capture_menu_and_chip"); continue; }
        const ShellPalette& pal = brand_theme()->palette(dark);
        const wxBitmap chip_bmp = chip->snapshot();
        const wxSize msize = shown->GetClientSize();
        const int margin = 16, gap = 4;
        const int width = std::max(chip_bmp.GetWidth(), msize.x) + 2 * margin;
        const int height = chip_bmp.GetHeight() + gap + msize.y + 2 * margin;
        wxBitmap out(width, height);
        {
            wxMemoryDC dc(out);
            dc.SetBackground(wxBrush(pal.surface_canvas));
            dc.Clear();
            const int right = width - margin;
            dc.DrawBitmap(chip_bmp, right - chip_bmp.GetWidth(), margin);
            const wxPoint origin(right - msize.x, margin + chip_bmp.GetHeight() + gap);
            dc.SetPen(wxPen(pal.border_subtle));
            dc.SetBrush(wxBrush(pal.surface_raised));
            dc.DrawRoundedRectangle(wxRect(origin, msize).Deflate(1),
                                    shown->FromDIP(brand_theme()->metrics().popover.radius));
            for (wxWindow* child : shown->GetChildren()) {
                if (!child->IsShown()) continue;
                const wxPoint at = origin + child->GetPosition();
                if (auto* button = dynamic_cast<HeaderButton*>(child)) {
                    dc.DrawBitmap(button->snapshot(), at);
                } else if (auto* text = dynamic_cast<wxStaticText*>(child)) {
                    dc.SetFont(text->GetFont());
                    dc.SetTextForeground(text->GetForegroundColour());
                    dc.DrawText(text->GetLabel(), at);
                } else {
                    dc.SetPen(*wxTRANSPARENT_PEN);
                    dc.SetBrush(wxBrush(child->GetBackgroundColour()));
                    dc.DrawRectangle(wxRect(at, child->GetSize()));
                }
            }
        }
        save_pane(std::string("header-printer-menu-") + (dark ? "dark" : "light"), out);
        shown->close();
        wxYield();
    }
    header->apply_appearance(false);
    header->open_printer_menu();
    wxYield();
    menu = visible_header_menu();
    other = menu ? dynamic_cast<HeaderButton*>(wxWindow::FindWindowByName(wxString::FromUTF8(other_name), menu)) : nullptr;
}

